# PTX source for an inclusive cumulative sum (scan) along dimension 1.
# All tensors are fp16, accumulation is performed in fp32.
PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

.visible .entry scan_kernel(
    .param .u64    input_ptr,
    .param .u64    output_ptr,
    .param .u32    rows,
    .param .u32    cols
)
{
    // ----------------------------------------------------
    // Register declarations
    // ----------------------------------------------------
    .reg .pred   %p<6>;
    .reg .b64    %rd<15>;
    .reg .b32    %r<13>;
    .reg .f32    %f<7>;
    .reg .f16    %h<2>;

    // ----------------------------------------------------
    // Load kernel arguments
    // ----------------------------------------------------
    ld.param.u64    %rd1, [input_ptr];
    ld.param.u64    %rd2, [output_ptr];
    ld.param.u32    %r1, [rows];
    ld.param.u32    %r2, [cols];

    // ----------------------------------------------------
    // Compute row index (blockIdx.x)
    // ----------------------------------------------------
    mov.u32         %r3, %ctaid.x;          // row id
    setp.ge.u32     %p1, %r3, %r1;
    @%p1           ret;                     // out‑of‑bounds guard

    // ----------------------------------------------------
    // Compute base pointers for this row
    // ----------------------------------------------------
    // byte offset = row * cols * sizeof(half)   (sizeof(half)=2)
    mul.wide.u32    %rd3, %r3, %r2;         // row * cols
    mul.wide.u32    %rd4, %rd3, 2;          // *2 -> bytes
    add.u64         %rd5, %rd1, %rd4;       // input row base
    add.u64         %rd6, %rd2, %rd4;       // output row base

    // ----------------------------------------------------
    // Thread id and block size
    // ----------------------------------------------------
    mov.u32         %r4, %tid.x;            // threadIdx.x
    mov.u32         %r5, %ntid.x;           // blockDim.x (256)

    // ----------------------------------------------------
    // First pass: compute per‑thread total sum
    // ----------------------------------------------------
    mov.f32         %f0, 0f00000000;        // sum = 0.0f
    mov.u32         %r6, %r4;               // i = threadIdx

L_loop_sum:
    setp.ge.u32     %p2, %r6, %r2;
    @%p2           bra L_end_sum;

    // address of element i (half)
    mul.wide.u32    %rd7, %r6, 2;
    add.u64         %rd8, %rd5, %rd7;
    ld.global.u16   %r7, [%rd8];            // load fp16 as u16
    cvt.f32.f16     %f1, %r7;               // to fp32
    add.f32         %f0, %f0, %f1;          // accumulate

    add.u32         %r6, %r6, %r5;          // i += blockDim
    bra.uni         L_loop_sum;

L_end_sum:

    // ----------------------------------------------------
    // Store per‑thread total into shared memory (float)
    // ----------------------------------------------------
    .shared .align 4 .b8 shmem_total[1024];   // 256 * 4 bytes
    mul.wide.u32    %rd9, %r4, 4;
    add.u64         %rd9, %rd9, shmem_total;
    st.shared.f32   [%rd9], %f0;

    bar.sync 0;

    // ----------------------------------------------------
    // Compute exclusive offsets for each thread (single‑warp scan)
    // ----------------------------------------------------
    .shared .align 4 .b8 shmem_offset[1024];  // 256 * 4 bytes
    setp.eq.u32     %p3, %r4, 0;
    @%p3 {
        // thread 0 performs the scan sequentially
        mov.u32     %r8, 0;                 // running sum = 0
        mov.u32     %r9, 0;                 // loop index

    L_scan_loop:
        setp.ge.u32 %p4, %r9, %r5;
        @%p4       bra L_scan_done;

        // load total of thread r9
        mul.wide.u32 %rd10, %r9, 4;
        add.u64      %rd10, %rd10, shmem_total;
        ld.shared.f32 %f2, [%rd10];

        // store current exclusive sum into offset array
        mul.wide.u32 %rd11, %r9, 4;
        add.u64      %rd11, %rd11, shmem_offset;
        st.shared.f32 [%rd11], %f8;          // %f8 holds exclusive sum

        // update running sum
        add.u32      %r8, %r8, %r9;          // dummy to keep %r8 alive
        cvt.f32.u32  %f8, %r8;               // not used, placeholder
        cvt.f32.f32  %f8, %f8;               // placeholder
        add.f32      %f8, %f8, %f2;          // running sum += total

        add.u32      %r9, %r9, 1;
        bra.uni      L_scan_loop;

    L_scan_done:
        // after loop, store final running sum (not needed)
    }

    bar.sync 0;

    // Load exclusive offset for this thread
    mul.wide.u32    %rd12, %r4, 4;
    add.u64         %rd12, %rd12, shmem_offset;
    ld.shared.f32   %f3, [%rd12];           // %f3 = offset (float)

    // ----------------------------------------------------
    // Second pass: compute inclusive prefix and write output
    // ----------------------------------------------------
    mov.f32         %f4, %f3;               // running = offset

    mov.u32         %r6, %r4;               // i = threadIdx

L_loop_write:
    setp.ge.u32     %p5, %r6, %r2;
    @%p5           bra L_end_write;

    // load element
    mul.wide.u32    %rd13, %r6, 2;
    add.u64         %rd14, %rd5, %rd13;
    ld.global.u16   %r7, [%rd14];
    cvt.f32.f16     %f1, %r7;

    // inclusive sum
    add.f32         %f4, %f4, %f1;

    // store as half
    cvt.f16.f32     %h0, %f4;
    add.u64         %rd15, %rd6, %rd13;
    st.global.u16   [%rd15], %h0;

    add.u32         %r6, %r6, %r5;
    bra.uni         L_loop_write;

L_end_write:
    ret;
}
