# Python wrapper that loads and launches the PTX kernel
# ----------------------------------------------------
import torch
import torch.nn as nn

# ptx_harness is assumed to provide these utilities
# from ptx_harness import ptx_load, ptx_launch

class ModelNew(nn.Module):
    def __init__(self, dim):
        super().__init__()
        self.dim = dim
        # The kernel always scans along dimension 1 (columns)
        self.module = ptx_load(PTX_SOURCE)
        self.kernel_name = "scan_kernel"

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure input is contiguous fp16
        x = x.contiguous()
        out = torch.empty_like(x)

        rows = x.shape[0]
        cols = x.shape[1] if x.dim() > 1 else 1

        # Launch configuration
        grid  = (rows, 1, 1)          # one block per row
        block = (256, 1, 1)           # 256 threads per block

        args = [
            x.data_ptr(),
            out.data_ptr(),
            rows,
            cols
        ]

